        fillCorrectIndex: Int,
        seq: List<String>? = null,
        isRevision: Boolean = false,
        isFinalAssessment: Boolean = false,
        sourceRef: String = SRC_JAZARI
    ): LessonSpec = LessonSpec(
        title = title,
        arabic = arabic,
        pronunciation = pronunciation,
        objective = objective,
        explanation = explanation,
        keyRule = keyRule,
        wrongStatement = wrongStatement,
